CREATE TABLE IF NOT EXISTS clubs(id SERIAL PRIMARY KEY,name VARCHAR(120) UNIQUE NOT NULL,description TEXT,logo_url TEXT,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS users(id SERIAL PRIMARY KEY,full_name VARCHAR(160) NOT NULL,group_no VARCHAR(50),club_id INT REFERENCES clubs(id) ON DELETE SET NULL,role VARCHAR(20) NOT NULL DEFAULT 'MEMBER' CHECK(role IN ('ADMIN','CHAIR','MEMBER')),member_code VARCHAR(40) UNIQUE NOT NULL,password_hash TEXT NOT NULL,active BOOLEAN DEFAULT true,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS news(id SERIAL PRIMARY KEY,title VARCHAR(220) NOT NULL,summary TEXT,content TEXT,category VARCHAR(80) DEFAULT 'Xəbər',cover_url TEXT,author_id INT REFERENCES users(id) ON DELETE SET NULL,published BOOLEAN DEFAULT true,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS events(id SERIAL PRIMARY KEY,title VARCHAR(220) NOT NULL,description TEXT,event_date TIMESTAMPTZ NOT NULL,location VARCHAR(200),club_id INT REFERENCES clubs(id) ON DELETE SET NULL,created_by INT REFERENCES users(id) ON DELETE SET NULL,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS leadership(id SERIAL PRIMARY KEY,full_name VARCHAR(160) NOT NULL,title VARCHAR(120) NOT NULL,bio TEXT,photo_url TEXT,sort_order INT DEFAULT 0,active BOOLEAN DEFAULT true);
CREATE TABLE IF NOT EXISTS event_attendance(id SERIAL PRIMARY KEY,event_id INT REFERENCES events(id) ON DELETE CASCADE,user_id INT REFERENCES users(id) ON DELETE CASCADE,status VARCHAR(20) DEFAULT 'GOING',UNIQUE(event_id,user_id));
CREATE TABLE IF NOT EXISTS announcements(id SERIAL PRIMARY KEY,title VARCHAR(200) NOT NULL,body TEXT NOT NULL,club_id INT REFERENCES clubs(id) ON DELETE CASCADE,created_by INT REFERENCES users(id) ON DELETE SET NULL,created_at TIMESTAMPTZ DEFAULT now());
